//! Native requestSubmit runs in the current caller job before navigation.
use super::*;
fn fixture(source:&str)->(Document,Forms,Page){
 let mut doc=crate::html::parse("<body><form id=owner action='/send' method=post><input id=a name=a required><button id=chosen name=choice value=chosen>Send</button><button id=skip name=choice value=skip formnovalidate>Skip</button></form><form id=other><button id=foreign>Other</button></form><button id=plain type=button>Plain</button></body>");doc.scripting_enabled=true;let mut forms=Forms::new(&doc);let mut page=Page::new();let location=crate::navigation::address("https://request-submit.test/source",&crate::navigation::Location::home()).unwrap();page.set_location(&location);page.set_resource_base(&location);let out=page.start(&mut doc,&mut forms,&[Script{node:0,label:"Native requestSubmit witness".into(),source:source.into()}]);assert_eq!(out.errors,0,"{}",page.report());(doc,forms,page)
}
#[test]
fn form_request_canonical_arguments_and_canceled_synchronous_submit(){
 let(_,_,mut page)=fixture("var form=document.getElementById('owner'),button=document.getElementById('chosen'),P=HTMLFormElement.prototype,R=P.requestSubmit,d=Object.getOwnPropertyDescriptor(P,'requestSubmit');if(typeof R!=='function'||R.name!=='requestSubmit'||R.length!==0||!d.writable||!d.enumerable||!d.configurable||form.requestSubmit!==R||Object.prototype.hasOwnProperty.call(form,'requestSubmit'))throw 'canonical';for(var value of [{},1,'chosen',document.getElementById('plain')]){var denied=false;try{R.call(form,value);}catch(e){denied=e instanceof TypeError;}if(!denied)throw 'submit button brand';}var foreign=false;try{form.requestSubmit(document.getElementById('foreign'));}catch(e){foreign=e instanceof DOMException&&e.name==='NotFoundError';}if(!foreign)throw 'owner';document.getElementById('a').value='Ready';var calls=0,last='';form.onsubmit=function(e){if(!(e instanceof SubmitEvent)||!e.isTrusted||!e.bubbles||!e.cancelable||e.composed)throw 'metadata';calls++;last=e.submitter===null?'none':e.submitter.id;e.preventDefault();};if(form.requestSubmit(button)!==undefined||calls!==1||last!=='chosen')throw 'synchronous';form.requestSubmit();form.requestSubmit(null);form.requestSubmit(undefined);if(calls!==4||last!=='none')throw 'nullable';");assert!(page.take_navigation().is_none());
}

#[test]
fn form_request_validation_callbacks_recursion_other_forms_and_microtasks(){
 let(doc,_,mut page)=fixture("var form=document.getElementById('owner'),chosen=document.getElementById('chosen'),a=document.getElementById('a'),other=document.getElementById('other'),order='';a.oninvalid=function(e){order+='i';a.value='Fixed';form.requestSubmit(chosen);e.preventDefault();};other.onsubmit=function(e){if(e.submitter!==document.getElementById('foreign'))throw 'nested metadata';order+='o';e.preventDefault();};form.onsubmit=function(e){order+='s';form.requestSubmit(chosen);other.requestSubmit(document.getElementById('foreign'));order+='t';e.preventDefault();Promise.resolve().then(function(){order+='m';document.title=order;});};form.requestSubmit(chosen);if(order!=='i')throw 'invalid attempt submitted';order+='r';form.requestSubmit(chosen);if(order!=='irsot')throw 'nested ordering '+order;order+='e';");assert_eq!(doc.title,"irsotem");assert!(page.take_navigation().is_none());assert!(page.state.form_requests.is_empty());assert!(page.state.form_validations.is_empty());assert!(page.state.synthetic_dispatches.is_empty());
}
#[test]
fn form_request_required_snapshot_survives_repairs_and_removed_later_control(){
 let(_,_,mut page)=fixture("var form=document.getElementById('owner'),chosen=document.getElementById('chosen'),a=document.getElementById('a'),b=document.createElement('input'),calls='',submitted=0;b.required=true;b.name='b';form.appendChild(b);a.oninvalid=function(e){calls+='a';a.value='Fixed';b.value='Fixed';b.remove();e.preventDefault();};b.oninvalid=function(e){if(b.isConnected||e.target!==b)throw 'saved target';calls+='b';e.preventDefault();};form.onsubmit=function(e){submitted++;e.preventDefault();};form.requestSubmit(chosen);if(calls!=='ab'||submitted!==0)throw 'snapshot';form.requestSubmit(chosen);if(submitted!==1)throw 'fresh values';");assert!(page.take_navigation().is_none());
}
#[test]
fn form_request_novalidate_and_disabled_explicit_submitters(){
 fixture("var form=document.getElementById('owner'),chosen=document.getElementById('chosen'),a=document.getElementById('a'),calls=0,submitted=0,last;form.addEventListener('invalid',function(e){calls++;e.preventDefault();},true);form.onsubmit=function(e){submitted++;last=e.submitter;e.preventDefault();};form.requestSubmit(document.getElementById('skip'));if(calls!==0||submitted!==1||last!==document.getElementById('skip'))throw 'submitter override';form.noValidate=true;form.requestSubmit();if(calls!==0||submitted!==2||last!==null)throw 'form override';form.noValidate=false;chosen.disabled=true;form.requestSubmit(chosen);if(calls!==1||submitted!==2)throw 'disabled still validates';a.value='Ready';form.requestSubmit(chosen);if(calls!==1||submitted!==3||last!==chosen)throw 'disabled submitter';");
}
#[test]
fn form_request_serialization_observes_submit_callbacks_without_revalidation(){
 let(_,_,mut page)=fixture("var form=document.getElementById('owner'),a=document.getElementById('a'),chosen=document.getElementById('chosen');a.value='Before';form.onsubmit=function(e){if(e.submitter!==chosen)throw 'chosen';a.value='';chosen.value='Changed';};form.requestSubmit(chosen);a.value='After';");let navigation=page.take_navigation().unwrap();assert_eq!(navigation.target.display(),"https://request-submit.test/send");let crate::http::Request::FormPost{body,..}=navigation.request else{panic!("Expected actual POST payload")};assert_eq!(body,b"a=&choice=Changed");assert!(navigation.form_policy.is_some());assert_eq!(page.state.navigation_requests,1);
 let(_,_,mut page)=fixture("var form=document.getElementById('owner'),a=document.getElementById('a'),chosen=document.getElementById('chosen');a.value='Ready';chosen.disabled=true;chosen.formMethod='get';chosen.formAction='/disabled';form.requestSubmit(chosen);");let navigation=page.take_navigation().unwrap();assert_eq!(navigation.target.display(),"https://request-submit.test/disabled?a=Ready");assert!(!navigation.request.is_post());
 let(_,_,mut page)=fixture("var form=document.getElementById('owner');document.getElementById('a').value='Ready';form.requestSubmit();");let navigation=page.take_navigation().unwrap();let crate::http::Request::FormPost{body,..}=navigation.request else{panic!("Expected POST")};assert_eq!(body,b"a=Ready");
}
#[test]
fn form_request_named_mask_detached_and_unavailable_backends(){
 let(_,_,mut page)=fixture("var form=document.getElementById('owner'),R=HTMLFormElement.prototype.requestSubmit,named=document.createElement('input');named.name='requestSubmit';form.appendChild(named);if(form.requestSubmit!==named)throw 'mask';document.getElementById('a').value='Ready';form.onsubmit=function(e){e.preventDefault();};R.call(form);var detached=document.createElement('form'),field=document.createElement('input');field.required=true;detached.appendChild(field);detached.addEventListener('invalid',function(){throw 'detached submission';},true);detached.onsubmit=function(){throw 'detached submit';};if(R.call(detached)!==undefined)throw 'detached return';var inert=document.implementation.createHTMLDocument('inert').createElement('form'),denied=false;try{R.call(inert);}catch(e){denied=e instanceof DOMException&&e.name==='NotSupportedError';}if(!denied)throw 'inert backend';var a=document.getElementById('a'),view=a.validity,invalid=0,submitted=0;a.pattern='[A-Z]+';a.oninvalid=function(e){if(!e.isTrusted||e.target!==a||!view.patternMismatch||view.valid)throw 'native pattern invalid';invalid++;e.preventDefault();};form.onsubmit=function(e){if(!e.isTrusted||e.submitter!==null||!view.valid)throw 'native repaired submission';submitted++;e.preventDefault();};if(!view.patternMismatch||view.valid||R.call(form)!==undefined||invalid!==1||submitted!==0)throw 'pattern blocks canonical request';a.value='READY';if(view.patternMismatch||!view.valid||R.call(form)!==undefined||invalid!==1||submitted!==1||form.requestSubmit!==named)throw 'pattern repair preserves named mask';if(!delete detached.requestSubmit||typeof detached.requestSubmit!=='function')throw 'inherited delete';");assert!(page.take_navigation().is_none());assert!(page.state.form_requests.is_empty());
}
#[test]
fn form_request_resource_refusal_unwinds_then_fresh_job_recovers(){
 for mode in 0..4{
  let(mut doc,mut forms,mut page)=fixture("document.getElementById('a').value='Ready';");let object=node_handle((0..doc.nodes.len()).find(|&n|doc.attr(n,"id")==Some("owner")).unwrap());page.begin_job();let work=page.state.host_work;let copy=page.state.copy_work;let limit=page.state.retained_limit;let retained=page.state.retained;let deadline=page.state.execution_deadline;
  match mode{0=>page.state.host_work=0,1=>page.state.copy_work=0,2=>page.state.retained_limit=retained,_=>page.state.execution_deadline=Some(Instant::now())};if mode==1{let token=Bridge{doc:&mut doc,forms:&mut forms,state:&mut page.state}.begin_native_form_request(object,&[]).unwrap().unwrap();assert!(Bridge{doc:&mut doc,forms:&mut forms,state:&mut page.state}.native_form_request_validation(token).is_err());Bridge{doc:&mut doc,forms:&mut forms,state:&mut page.state}.finish_native_form_request(token);}else{assert!(Bridge{doc:&mut doc,forms:&mut forms,state:&mut page.state}.begin_native_form_request(object,&[]).is_err(),"mode {mode}");}assert!(page.state.form_requests.is_empty());assert!(page.state.form_validations.is_empty());assert!(page.state.synthetic_dispatches.is_empty());assert!(page.take_navigation().is_none());assert_eq!(page.state.retained,retained+page.state.form_requests.capacity()*std::mem::size_of::<script_form_request::Pending>());page.state.host_work=work;page.state.copy_work=copy;page.state.retained_limit=limit;page.state.execution_deadline=deadline;
  page.begin_job();let outcome=page.console_eval(&mut doc,&mut forms,"document.getElementById('owner').requestSubmit();");assert_eq!(outcome.errors,0,"{}",page.report());assert!(page.take_navigation().is_some());assert!(page.state.form_requests.is_empty());
 }
}
#[test]
fn form_request_nested_fatal_callback_preserves_commits_and_releases_all_guards(){
 let(mut doc,mut forms,mut page)=fixture("var form=document.getElementById('owner'),chosen=document.getElementById('chosen'),a=document.getElementById('a'),other=document.getElementById('other');a.value='Ready';other.onsubmit=function(){a.value='Committed';while(true){a.value;}};form.onsubmit=function(){other.requestSubmit(document.getElementById('foreign'));};");page.begin_job();page.state.host_work=30_000;let error=page.runtime.execute("form.requestSubmit(chosen);",&mut Bridge{doc:&mut doc,forms:&mut forms,state:&mut page.state}).unwrap_err();assert!(error.contains("work")||error.contains("step")||error.contains("time"),"{error}");assert!(page.state.form_requests.is_empty());assert!(page.state.form_validations.is_empty());assert!(page.state.synthetic_dispatches.is_empty());assert!(page.state.created_events.iter().all(|e|!e.dispatching));assert!(page.take_navigation().is_none());let node=(0..doc.nodes.len()).find(|&n|doc.attr(n,"id")==Some("a")).unwrap();assert_eq!(forms.controls[&node].value.text(),"Committed");page.begin_job();let out=page.console_eval(&mut doc,&mut forms,"form.onsubmit=null;other.onsubmit=null;form.requestSubmit(chosen);");assert_eq!(out.errors,0,"{}",page.report());assert!(page.take_navigation().is_some());assert!(page.state.form_requests.is_empty());
}
#[test]
fn form_request_saved_child_authority_csp_origin_and_queue_refusal(){
 let(mut doc,mut forms,mut page)=fixture("var form=document.getElementById('owner'),frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var request=frame.contentWindow.HTMLFormElement.prototype.requestSubmit;document.getElementById('a').value='Ready';");page.set_location(&crate::navigation::address("https://foreign-request.test/",&crate::navigation::Location::home()).unwrap());page.begin_job();let error=page.runtime.execute("request.call(form);",&mut Bridge{doc:&mut doc,forms:&mut forms,state:&mut page.state}).unwrap_err();assert!(error.contains("origin")||error.contains("Security"),"{error}");assert!(page.take_navigation().is_none());assert!(page.state.form_requests.is_empty());page.set_location(&crate::navigation::address("https://request-submit.test/source",&crate::navigation::Location::home()).unwrap());page.begin_job();page.runtime.execute("request.call(form);",&mut Bridge{doc:&mut doc,forms:&mut forms,state:&mut page.state}).unwrap();assert!(page.take_navigation().is_some());
 for mode in 0..3{
  let(mut doc,mut forms,mut page)=fixture("var form=document.getElementById('owner');document.getElementById('a').value='Ready';");if mode==0{page.state.dynamic.policy.add_header("form-action 'none'");}else if mode==1{let out=page.console_eval(&mut doc,&mut forms,"form.action='https://elsewhere.test/send';");assert_eq!(out.errors,0);}else{page.state.navigation_requests=16;}page.begin_job();assert!(page.runtime.execute("form.requestSubmit();",&mut Bridge{doc:&mut doc,forms:&mut forms,state:&mut page.state}).is_err());assert!(page.take_navigation().is_none());assert!(page.state.form_requests.is_empty());assert!(page.state.form_validations.is_empty());assert!(page.state.synthetic_dispatches.is_empty());
 }
}
